package com.yuri.music;
import android.app.Activity;import org.json.*;import java.net.*;import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;
final class YouTubeDownloads{
 static JSONObject save(Activity owner,JSONObject r)throws Exception{String id=r.getString("id");URL url=new URL(r.getString("url"));JSONObject metadata=r.getJSONObject("song");if(!id.matches("[A-Za-z0-9_-]{11}")||!metadata.optString("id").equals(id)||!url.getProtocol().equals("https")||!url.getHost().endsWith(".googlevideo.com")||url.getUserInfo()!=null)throw new IOException("Faixa inválida.");HttpURLConnection c=(HttpURLConnection)url.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(20000);c.setReadTimeout(45000);try{if(c.getResponseCode()!=200)throw new IOException("O YouTube recusou o download. Tente novamente.");String type=c.getContentType();if(type==null||!type.startsWith("audio/"))throw new IOException("A resposta não é áudio.");File dir=new File(owner.getFilesDir(),"Music");dir.mkdirs();String name=id+(type.contains("webm")?".webm":".m4a");File target=new File(dir,name),part=File.createTempFile(id,".part",dir);try{try(InputStream input=c.getInputStream();FileOutputStream output=new FileOutputStream(part)){byte[] buffer=new byte[65536];int n;long total=0;while((n=input.read(buffer))!=-1){total+=n;if(total>300L*1024*1024)throw new IOException("Faixa muito grande.");output.write(buffer,0,n);}output.getFD().sync();}Files.move(part.toPath(),target.toPath(),StandardCopyOption.REPLACE_EXISTING);metadata.put("file",name);File temp=new File(dir,id+".json.tmp");Files.write(temp.toPath(),metadata.toString().getBytes(StandardCharsets.UTF_8));Files.move(temp.toPath(),new File(dir,id+".json").toPath(),StandardCopyOption.REPLACE_EXISTING);return new JSONObject().put("ok",true);}finally{part.delete();}}finally{c.disconnect();}}
}
